            args.sources.append(a)
            i += 1
            continue
        if a == "--":
            passthrough = True
            i += 1
            continue
        if a == "--help":
            sys.stdout.write(FULL_HELP_TEMPLATE.format(prog=prog_name()))
            sys.exit(0)
        if a == "--version":
            sys.stdout.write(VERSION + "\n")
            sys.exit(0)
        if a == "--install-pre-commit":
            args.install = True
            i += 1
            continue
        if a == "--strict-ignore":
            args.strict = True
            i += 1
            continue
        if a == "--only-matching":
