@dataclass
class Args:
    install: bool = False
    strict: bool = False
    only_matching: bool = False
    patterns: list = None
    sources: list = None


def prog_name():
    return os.path.basename(sys.argv[0]) or "executable"


def print_unexpected(arg):
    p = prog_name()
    sys.stderr.write(f"error: unexpected argument '{arg}' found\n\n")
    sys.stderr.write(f"  tip: to pass '{arg}' as a value, use '-- {arg}'\n\n")
    sys.stderr.write(f"Usage: {p} [OPTIONS] [Source files]...\n\n")
    sys.stderr.write("For more information, try '--help'.\n")
    sys.exit(2)


def parse_args(argv):
    args = Args(patterns=[], sources=[])
    i = 1
    passthrough = False
    while i < len(argv):
        a = argv[i]
        if passthrough:
            args.sources.append(a)
            i += 1
            continue
        if a == "--":
            passthrough = True
            i += 1
            continue
        if a == "--help":
            sys.stdout.write(FULL_HELP_TEMPLATE.format(prog=prog_name()))
            sys.exit(0)
        if a == "--version":
            sys.stdout.write(VERSION + "\n")
            sys.exit(0)
        if a == "--install-pre-commit":
            args.install = True
            i += 1
            continue
        if a == "--strict-ignore":
            args.strict = True
            i += 1
            continue
        if a == "--only-matching":
            args.only_matching = True
            i += 1
            continue
        if a == "--additional-pattern":
            if i + 1 >= len(argv):
                sys.stderr.write("error: a value is required for '--additional-pattern <ADDITIONAL_PATTERNS>' but none was supplied\n\n")
                sys.stderr.write("For more information, try '--help'.\n")
                sys.exit(2)
            args.patterns.append(argv[i+1])
            i += 2
            continue
        if a.startswith("--additional-pattern="):
            args.patterns.append(a.split("=", 1)[1])
            i += 1
            continue
        if a.startswith("--"):
            print_unexpected(a)
        if a.startswith("-") and a != "-":
            # clap-style short flag clusters: the first action flag wins
            if len(a) >= 2:
                first = a[1]
                if first == "h":
                    sys.stdout.write(SHORT_HELP_TEMPLATE.format(prog=prog_name()))
                    sys.exit(0)
                if first == "V":
                    sys.stdout.write(VERSION + "\n")
                    sys.exit(0)
            print_unexpected(a)
        args.sources.append(a)
        i += 1
    return args


def rust_os_error(e):
    if isinstance(e, FileNotFoundError):
        return "No such file or directory (os error 2)"
    if isinstance(e, PermissionError):
        return "Permission denied (os error 13)"
    if isinstance(e, IsADirectoryError):
        return "Is a directory (os error 21)"
    errno = getattr(e, 'errno', None)
    if errno:
        # Python's strerror is close to Rust's display on Linux.
        return f"{e.strerror} (os error {errno})"
    return str(e)


def install_pre_commit(sources):
    if not sources:
        sources = ["."]
    for src in sources:
        git_dir = os.path.join(src, ".git")
        if not os.path.isdir(git_dir):
            sys.stderr.write("Error: .git directory not found\n")
            return 2
        hook_path = os.path.join(git_dir, "hooks", "pre-commit")
        try:
            try:
                with open(hook_path, "r", encoding="utf-8", errors="ignore") as f:
                    contents = f.read()
                if HOOK_LINE.strip() in contents:
                    sys.stderr.write("Error: pre-commit hook has already been installed\n")
                    return 2
            except FileNotFoundError:
                # Opening for append below will create the file, but only if hooks/ exists.
                pass
            with open(hook_path, "a", encoding="utf-8") as f:
                f.write(HOOK_LINE)
        except OSError as e:
            sys.stderr.write(f"Error: {rust_os_error(e)}\n")
            return 2
    return 0


@dataclass
class IgnorePattern:
    raw: str
    pattern: str
    dir_only: bool
    has_slash: bool

    @staticmethod
    def from_line(line):
        raw = line.rstrip(' \t\r')
        pat = raw
        while pat.startswith('/'):
            pat = pat[1:]
        dir_only = pat.endswith('/')
        while pat.endswith('/'):
            pat = pat[:-1]
        has_slash = '/' in pat
        return IgnorePattern(raw=raw, pattern=pat, dir_only=dir_only, has_slash=has_slash)

    def _component_match(self, comp):
        return fnmatch.fnmatchcase(comp, self.pattern)

    def matches(self, rel, is_dir):
        if not self.pattern:
            return False
        rel = rel.replace(os.sep, '/')
        if rel in ('', '.'):
            return False
        rel = rel.lstrip('./') if rel.startswith('./') else rel
        comps = [c for c in rel.split('/') if c and c != '.']
        if not comps:
            return False
        if self.has_slash:
            pat = self.pattern
            if self.dir_only:
                return rel == pat or rel.startswith(pat + '/')
            # A slash pattern is relative to the current directory. If it names a
            # directory, descendants are ignored as well.
            return fnmatch.fnmatchcase(rel, pat) or rel.startswith(pat + '/')
        else:
            if self.dir_only:
                # Match any directory component. For a directory path, the final
                # component is also a directory; for a file path it is not.
                dirs = comps if is_dir else comps[:-1]
                return any(self._component_match(c) for c in dirs)
            # Basename pattern: match a file or directory name anywhere; if a
            # directory component matches, its whole subtree is ignored.
            return any(self._component_match(c) for c in comps)


class SecretsIgnore:
    def __init__(self, cwd):
        self.cwd = os.path.abspath(cwd)
        self.patterns = []
        self.secrets = set()
        self._load()

    def _load(self):
        path = os.path.join(self.cwd, ".secretsignore")
        try:
            with open(path, "rb") as f:
                data = f.read()
        except OSError:
            return
        in_secrets = False
        for raw in data.splitlines():
            line = raw.decode('latin-1')
            if line.strip() == "[secrets]":
                in_secrets = True
                continue
            if not in_secrets:
                p = line.rstrip(' \t\r')
                if not p or p.startswith('#'):
                    continue
                self.patterns.append(IgnorePattern.from_line(p))
            else:
                # Exact matched values. Blank/comment lines are accepted by the
                # format but do not matter for the built-in detectors; skipping
                # them mirrors normal ignore-file expectations.
                if line == '' or line.startswith('#'):
                    continue
                self.secrets.add(line.rstrip('\r'))

    def rel_for(self, path):
        try:
            ap = os.path.abspath(path)
            rel = os.path.relpath(ap, self.cwd)
        except Exception:
            rel = path
        return rel.replace(os.sep, '/')

    def matching_patterns(self, path, is_dir):
        rel = self.rel_for(path)
        return [p for p in self.patterns if p.matches(rel, is_dir)]

    def is_ignored(self, path, is_dir, disabled_patterns=None):
        disabled = disabled_patterns or set()
        for p in self.patterns:
            if id(p) in disabled:
                continue
            if p.matches(self.rel_for(path), is_dir):
                return True
        return False


def shannon_entropy(s):
    if not s:
        return 0.0
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    n = len(s)
    ent = 0.0
    for c in counts.values():
        p = c / n
        ent -= p * math.log2(p)
    return ent


def has_alpha_sequence(s, n=5):
    low = s.lower()
    alpha = "abcdefghijklmnopqrstuvwxyz"
    rev = alpha[::-1]
    for i in range(0, len(alpha) - n + 1):
        if alpha[i:i+n] in low or rev[i:i+n] in low:
            return True
    return False


def has_long_run(s, n=6):
    last = None
    count = 0
    for ch in s:
        if ch == last:
            count += 1
            if count >= n:
                return True
        else:
            last = ch
            count = 1
    return False


def is_random(s):
    # The original applies a lightweight "random-looking" filter to captured
    # submatches. This implementation follows the observed behavior: simple
    # words/lowercase-only strings are ignored, while mixed/high-entropy tokens
    # and provider secrets pass when appropriate.
    if s is None:
        return False
    if len(s) < 4:
        return False
    low = s.lower()

    provider_prefixes = ("ghp_", "gho_", "ghu_", "ghs_", "ghr_", "github_pat_",
                         "glpat-", "xoxa-", "xoxb-", "xoxp-", "xoxr-", "xoxs-",
                         "sk_live_", "rk_live_", "npm_")
    if low.startswith(provider_prefixes):
        # These are intentionally caught by dedicated patterns when they are not
        # swallowed by an earlier generic key/token assignment.
        return False

    has_lower = any('a' <= c <= 'z' for c in s)
    has_upper = any('A' <= c <= 'Z' for c in s)
    has_digit = any('0' <= c <= '9' for c in s)
    has_other = any(not (('a' <= c <= 'z') or ('A' <= c <= 'Z') or ('0' <= c <= '9')) for c in s)

    if has_long_run(s):
        return False
    if has_lower and not has_upper and not has_digit:
        return False
    if has_lower and not has_upper and has_other and not has_digit:
        return False

    if not has_upper:
        common = ["correct", "horse", "battery", "staple", "notsecret", "secretsecret",
                  "secret", "random", "value", "qwerty", "asdf"]
        if any(w in low for w in common):
            return False
        if has_alpha_sequence(s, 5):
            return False
        if has_lower and ("12345" in s or "98765" in s):
            return False

    ent = shannon_entropy(s)
    if ent < 2.45:
        return False

    # Extremely repetitive block strings are not random in practice.
    if len(set(s)) <= 4 and len(s) >= 8:
        return False

    # Need at least some variety beyond a single repeated class, except all-
    # caps/all-digits strings with enough entropy are treated as random by the
    # observed tool.
    if not (has_upper or has_digit or has_other):
        return False
    return True


class Scanner:
    def __init__(self, only_matching, additional_patterns, ignore):
        self.only_matching = only_matching
        self.ignore = ignore
        self.found = False
        self.regex = None
        self.regex_groups = 0
        self._compile(additional_patterns)

    def _compile(self, additional_patterns):
        pattern = DEFAULT_REGEX
        for p in additional_patterns:
            pattern += "|" + p
        try:
            self.regex = re.compile(pattern, re.ASCII)
            self.regex_groups = self.regex.groups
        except re.error as e:
            sys.stderr.write("Error: regex parse error:\n")
            sys.stderr.write(f"    {pattern}\n")
            sys.stderr.write(f"error: {e}\n")
            sys.exit(2)

    def _selected_match(self, m):
        # Default regex has three captures: an outer default group, URL password,
        # and generic assignment value. The latter two are entropy-tested.
        try:
            g2 = m.group(2)
        except IndexError:
            g2 = None
        try:
            g3 = m.group(3)
        except IndexError:
            g3 = None
        if g2 is not None:
            return g2, True
        if g3 is not None:
            return g3, True
        # Additional regex captures start after the default groups. The tool uses
        # the first participating capture group for an additional pattern.
        for idx in range(4, self.regex_groups + 1):
            try:
                g = m.group(idx)
            except IndexError:
                break
            if g is not None:
                return g, True
        return m.group(0), False

    def scan_line(self, display_path, line_no, line_bytes):
        text = line_bytes.decode('latin-1')
        line_has_match = False
        selected_values = []
        for m in self.regex.finditer(text):
            # Rust's empty regex iterator does not report the terminal empty
            # match in the observed --only-matching output.
            if m.group(0) == '' and m.start() == len(text):
                continue
            selected, needs_random = self._selected_match(m)
            if needs_random and not is_random(selected):
                continue
            if selected in self.ignore.secrets:
                continue
            if self.only_matching:
                selected_values.append(selected)
            else:
                # For an empty additional pattern, non-empty lines are reported;
                # empty lines are not useful and were not printed in observation.
                if text != '' or m.group(0) != '':
                    line_has_match = True
        if self.only_matching:
            for val in selected_values:
                self.found = True
                prefix = f"{display_path}:{line_no}:".encode('utf-8', errors='surrogateescape')
                sys.stdout.buffer.write(prefix + val.encode('latin-1') + b"\n")
        elif line_has_match:
            self.found = True
            prefix = f"{display_path}:{line_no}:".encode('utf-8', errors='surrogateescape')
            sys.stdout.buffer.write(prefix + line_bytes + b"\n")

    def scan_file(self, path, display_path):
        try:
            with open(path, 'rb') as f:
                data = f.read()
        except OSError as e:
            sys.stderr.write(f"{display_path}: {rust_os_error(e)}\n")
            return
        # Split on LF, preserving CR and other bytes. Do not create an extra
        # final empty line for files ending in a newline.
        parts = data.split(b'\n')
        if parts and parts[-1] == b'':
            parts = parts[:-1]
        for idx, line in enumerate(parts, 1):
            self.scan_line(display_path, idx, line)


def is_hidden_name(name):
    return name.startswith('.') and name not in ('.', '..')


def path_is_under(path, root):
    try:
        ap = os.path.abspath(path)
        ar = os.path.abspath(root)
        return ap == ar or ap.startswith(ar.rstrip(os.sep) + os.sep)
    except Exception:
        return False


def display_join(root_display, root_path, child_path):
    rel = os.path.relpath(child_path, root_path)
    if rel == '.':
        return root_display.rstrip('/') or root_display
    return os.path.normpath(os.path.join(root_display, rel))


def walk_and_scan(scanner, ignore, src, strict):
    if src == '-':
        return
    display_src = src
    try:
        st = os.stat(src)
    except OSError as e:
        sys.stderr.write(f"{display_src}: {rust_os_error(e)}\n")
        return
    is_dir = os.path.isdir(src)
    explicit_ignored = ignore.is_ignored(src, is_dir)
    if strict and explicit_ignored:
        return

    disabled = set()
    if explicit_ignored and not strict:
        # Passing an ignored path explicitly overrides the pattern(s) that ignore
        # that path, but other ignore rules still apply beneath it.
        for p in ignore.matching_patterns(src, is_dir):
            disabled.add(id(p))

    if not is_dir:
        if not explicit_ignored or not strict:
            scanner.scan_file(src, display_src)
        return

    root_path = src
    root_display = display_src.rstrip('/') if display_src != '/' else display_src
    visited = set()

    def onerror(err):
        name = getattr(err, 'filename', None) or root_display
        # Try to format relative to the display root when possible.
        disp = name
        if path_is_under(name, root_path):
            disp = display_join(root_display, root_path, name)
        sys.stderr.write(f"{disp}: {rust_os_error(err)}\n")

    for dirpath, dirnames, filenames in os.walk(root_path, topdown=True, onerror=onerror, followlinks=True):
        try:
            real = os.path.realpath(dirpath)
            if real in visited:
                dirnames[:] = []
                continue
            visited.add(real)
        except OSError:
            pass

        # Prune hidden and ignored directories. The root itself has already been
        # accepted (possibly via explicit override), so only apply to children.
        keep_dirs = []
        for d in dirnames:
            p = os.path.join(dirpath, d)
            if is_hidden_name(d):
                continue
            if ignore.is_ignored(p, True, disabled):
                continue
            keep_dirs.append(d)
        dirnames[:] = keep_dirs

        for fn in filenames:
            if is_hidden_name(fn):
                continue
            p = os.path.join(dirpath, fn)
            if ignore.is_ignored(p, False, disabled):
                continue
            disp = display_join(root_display, root_path, p)
            scanner.scan_file(p, disp)


def main():
    args = parse_args(sys.argv)
    if args.install:
        sys.exit(install_pre_commit(args.sources))
    sources = args.sources if args.sources else ['.']
    ignore = SecretsIgnore(os.getcwd())
    scanner = Scanner(args.only_matching, args.patterns, ignore)
    for src in sources:
        walk_and_scan(scanner, ignore, src, args.strict)
    sys.exit(1 if scanner.found else 0)


if __name__ == '__main__':
    main()
